update ${database.prefix.userms}hou_user_info_detail
set user_bind_shop_id  = #{shopId},
    user_bind_store_id = #{storeId}
where user_id = #{userId}

update ${database.prefix.userms}hou_user_business_info
set is_approved   = #{isApproved},
    audit_comment = #{auditComment,jdbcType=VARCHAR}
where user_id = #{userId}

UPDATE ${database.prefix.userms}hou_user_info
SET user_name             = #{userName},
    user_mobile=#{userMobile}
where user_id = #{userId}

update ${database.prefix.userms}hou_user_info
set user_name     =#{param.nickname},
    user_nickname = #{param.nickname}
where user_id = #{param.userId}

