SELECT DISTINCT uuuid.user_id, user_mobile, user_reg_time, uuuid.user_avatar, uubc.bind_nickname AS user_name FROM ${database.prefix.userms}hou_user_info uuui LEFT JOIN ${database.prefix.userms}hou_user_info_detail uuuid ON uuui.user_id = uuuid.user_id LEFT JOIN ${database.prefix.userms}hou_user_bind_connect uubc ON uubc.user_id = uuui.user_id WHERE
and user_reg_time >= #{param.userStartRegTime}
and user_reg_time <= #{param.userEndRegTime}
and uubc.bind_nickname like concat('%', #{param.userName} ,'%')
and user_parent_id = #{param.userParentId}

select count(1)
from ${database.prefix.business}hou_supplier_shop_join_base
where user_id = #{userId}

select count(1)
from ${database.prefix.business}hou_shop_gate
where login_name = #{phone}

SELECT ta.user_id, ta.user_name, ta.user_mobile, b.user_gender, b.user_truename, b.user_birth, b.user_reg_time, ta.user_lastlogin_time FROM ${database.prefix.userms}hou_user_info ta LEFT JOIN ${database.prefix.userms}hou_user_info_detail b ON ta.user_id = b.user_id
and b.user_reg_time <= #{param.finishTime}
and b.user_reg_time >= #{param.StartTime}
and b.user_parent_id = #{param.shareUserId}
order by ta.user_id desc limit

select uuuid.user_parent_id,uuubc.bind_openid,uui.user_nickname,uui.user_id,uui.user_name, uui.password,uui.user_state,uui.user_lastlogin_time,uui.user_lastlogin_ip,uui.user_is_new,uui.is_business, uui.user_mobile,uuuid.user_avatar,uuuid.user_gender,uuuid.user_mobile_verify,uusb.seller_id,uusb.seller_name, uusb.shop_id,uusb.seller_is_admin,uusg.limits,uusb.shop_type from ${database.prefix.userms}hou_user_info uui LEFT JOIN ${database.prefix.userms}hou_user_seller_base uusb ON uusb.user_id = uui.user_id LEFT JOIN ${database.prefix.userms}hou_user_seller_group uusg ON uusg.group_id = uusb.seller_group_id LEFT JOIN ${database.prefix.userms}hou_user_info_detail uuuid ON uuuid.user_id = uui.user_id LEFT JOIN ${database.prefix.userms}hou_user_bind_connect uuubc ON uuubc.user_id = uui.user_id where uui.user_state BETWEEN 0 and 2
and uui.user_mobile = #{param.userMobile}
ORDER BY uuubc.bind_openid desc limit 1

SELECT ta.user_id, ta.user_name, ta.user_mobile, b.user_gender, b.user_truename, b.user_birth, b.user_reg_time, ta.user_lastlogin_time FROM ${database.prefix.userms}hou_user_info ta LEFT JOIN ${database.prefix.userms}hou_user_info_detail b ON ta.user_id = b.user_id where 1=1
and ta.user_id = #{param.userId}
and ta.user_name = #{param.userName}
and b.user_reg_time <= #{param.finishTime}
and b.user_reg_time >= #{param.startTime}
and ta.user_mobile like concat('%',#{param.userMobile},'%')
and b.user_birth = #{param.birthDate}
order by ta.user_lastlogin_time desc

select tag_id
from ${database.prefix.base}hou_base_tag_class
where member_id = #{memberId}

select tag_id, tag_name, tag_weight, tag_image, tag_describe
from ${database.prefix.userms}hou_user_tag_info
where tag_id = #{id}

SELECT ta.user_id, ta.user_name, ta.user_mobile, b.user_gender, b.user_truename, b.user_birth, b.user_reg_time, ta.user_lastlogin_time, count( ba.order_id ) AS orderCount, sum( ba.order_payment_amount ) AS sumAmount FROM ${database.prefix.userms}hou_user_info ta LEFT JOIN ${database.prefix.base}hou_base_tag_class tc ON tc.member_id = ta.user_id LEFT JOIN ${database.prefix.userms}hou_user_info_detail b ON ta.user_id = b.user_id LEFT JOIN (SELECT * FROM ${database.prefix.order}hou_order_base WHERE order_status NOT IN ( 1, 7 )) ba ON ta.user_id = ba.buyer_user_id left join ${database.prefix.userms}hou_user_plus_info pi on ta.user_id = pi.user_id left join (select user_id,sum(pay_price) as plusPrice from ${database.prefix.userms}hou_user_plus_order GROUP BY user_id) lishi on ta.user_id = lishi.user_id left join ${database.prefix.business}hou_shop_base sb on ta.user_id = sb.user_id
and sb.shop_business in (0,1)
and sb.shop_business = #{param.shopBusiness}
and sb.shop_self_support = #{param.shopSelfSupport}
and ta.user_id = #{param.userId}
and pi.thali_type is not null
and pi.thali_type is null
and ta.is_business = #{param.isBusiness}
and ta.user_name like concat('%',#{param.userName},'%')
and b.user_reg_time <= #{param.finishTime}
and b.user_reg_time >= #{param.startTime}
and ta.user_mobile like concat('%',#{param.userMobile},'%')
and b.user_birth = #{param.birthDate}
and tc.member_class_id = #{param.memberClassId}
group by ta.user_id order by b.user_reg_time desc

SELECT ta.user_id, ta.user_name, ta.user_mobile, b.user_gender, b.user_truename, b.user_birth, b.user_reg_time, b.out_shop_id, b.out_shop_name, b.out_shop_type, b.out_shop_code, b.region_name, b.office_name, b.zone_name, b.province, b.city, b.area, b.relation_sale_name, b.shop_detail_address, ta.user_integral, ta.is_business, ta.user_lastlogin_time, ta.currency_id, ta.currency_name, ta.balance, ta.customer_type_name, ta.user_state, tc.tag_id, tc.member_class_id, count( ba.order_id ) AS orderCount, sum( ba.order_payment_amount ) AS sumAmount, pi.thali_type, lishi.plusPrice as plusPrice, usb.shop_type as shopBusiness, sb.shop_self_support, b.is_black, b.place_order_status
FROM ${database.prefix.userms}hou_user_info ta LEFT JOIN ${database.prefix.base}hou_base_tag_class tc ON tc.member_id = ta.user_id LEFT JOIN ${database.prefix.userms}hou_user_info_detail b ON ta.user_id = b.user_id LEFT JOIN (SELECT * FROM ${database.prefix.order}hou_order_base WHERE order_status NOT IN ( 1, 7 )) ba ON ta.user_id = ba.buyer_user_id left join ${database.prefix.userms}hou_user_plus_info pi on ta.user_id = pi.user_id left join (select user_id,sum(pay_price) as plusPrice from ${database.prefix.userms}hou_user_plus_order GROUP BY user_id) lishi on ta.user_id = lishi.user_id LEFT JOIN ${database.prefix.userms}hou_user_seller_base usb ON ta.user_id = usb.user_id LEFT JOIN ${database.prefix.supplier}hou_shop_base sb ON usb.shop_id = sb.supplier_shop_id
ta.shop_id is null
and usb.shop_type = #{param.shopBusiness}
and sb.shop_self_support = #{param.shopSelfSupport}
and ta.user_id = #{param.userId}
and pi.thali_type is not null
and pi.thali_type is null
and ta.is_business = #{param.isBusiness}
and ta.user_name like concat('%',#{param.userName},'%')
and b.user_reg_time <= #{param.finishTime}
and b.user_reg_time >= #{param.startTime}
and ta.user_mobile like concat('%',#{param.userMobile},'%')
and b.user_birth = #{param.birthDate}
and tc.member_class_id = #{param.memberClassId}
and b.out_shop_name like concat('%',#{param.outShopName},'%')
and ta.customer_type_name = #{param.customerTypeName}
and ta.user_state = #{param.userState}
and b.is_black = #{param.isBlack}
group by ta.user_id order by b.user_reg_time desc

SELECT ta.user_id, ta.user_name, ta.user_mobile, b.user_gender, b.user_truename, b.user_birth, b.user_reg_time, b.out_shop_id, b.out_shop_name, b.out_shop_type, b.out_shop_code, b.region_name, b.office_name, b.zone_name, b.province, b.city, b.area, b.relation_sale_name, b.shop_detail_address, b.biz_shop_code, b.is_black, b.place_order_status, ta.user_integral, ta.is_business, ta.user_lastlogin_time, tc.tag_id, tc.member_class_id, ta.currency_id, ta.currency_name, ta.balance, ta.customer_type_name, ta.user_state, count( ba.order_id ) AS orderCount, sum( ba.order_payment_amount ) AS sumAmount FROM ${database.prefix.userms}hou_user_info ta LEFT JOIN ${database.prefix.base}hou_base_tag_class tc ON tc.member_id = ta.user_id LEFT JOIN ${database.prefix.userms}hou_user_info_detail b ON ta.user_id = b.user_id LEFT JOIN (SELECT * FROM ${database.prefix.order}hou_order_base WHERE order_status NOT IN ( 1, 7 )) ba ON ta.user_id = ba.buyer_user_id where ta.user_id not in (select user_id from ${database.prefix.userms}hou_user_business_info where is_approved!=1) and ta.shop_id = #{param.shopId}
and ta.user_id = #{param.userId}
and ta.is_business = #{param.isBusiness}
and ta.user_name like concat('%',#{param.userName},'%')
and b.user_reg_time <= #{param.finishTime}
and b.user_reg_time >= #{param.startTime}
and ta.user_mobile like concat('%',#{param.userMobile},'%')
and b.user_birth = #{param.birthDate}
and tc.member_class_id = #{param.memberClassId}
and b.out_shop_name like concat('%',#{param.outShopName},'%')
and ta.customer_type_name = #{param.customerTypeName}
and ta.user_state = #{param.userState}
and b.is_black = #{param.isBlack}
group by ta.user_id order by ta.user_id desc

select count(1)
from ${database.prefix.business}hou_shop_gate
where login_name = #{phone}
  and shop_type = 3
  and shop_id = #{shopId}

SELECT sum( oob.order_payment_amount ) AS totalAmount, uui.user_id, max( oob.order_create_time ) AS userLastShopTime, uui.user_lastlogin_time, uui.create_time AS memberCreateTime, uui.is_delete, uui.user_mobile, uui.user_name, uui.is_business FROM ${database.prefix.userms}hou_user_info uui LEFT JOIN ${database.prefix.order}hou_order_base oob ON uui.user_id = oob.buyer_user_id AND oob.order_status != 1 where uui.shop_id = #{param.shopId}
and uui.user_mobile = #{param.userMobile}
and uui.user_name = #{param.userName}
and uui.is_business = #{param.isBusiness}
and oob.order_create_time between #{param.shopStart} and #{param.shopEnd}
GROUP BY uui.user_id

SELECT sum( oob.order_payment_amount ) AS sumAmount, uui.user_id, max( oob.order_create_time ) AS userLastShopTime, uui.user_lastlogin_time, uui.create_time AS userRegTime, uui.is_delete, uui.user_mobile, uui.user_name, uui.is_business FROM ${database.prefix.userms}hou_user_info uui LEFT JOIN ${database.prefix.order}hou_order_base oob ON uui.user_id = oob.buyer_user_id WHERE uui.shop_id = #{param.shopId} and oob.order_status != 1
and uui.user_mobile = #{param.userMobile}
and uui.user_name = #{param.userName}
and uui.is_business = #{param.isBusiness}
and oob.order_create_time between #{param.shopStart} and #{param.shopEnd}
GROUP BY uui.user_id

